//! Animated, touchable starship-console lock screen.
//!
//! An original take on the "rounded elbows and pastel blocks" TV console
//! style. Every shape, label and color here is generated by this code: no
//! franchise fonts, logos, names or artwork.
//!
//! Interaction (purely cosmetic, never touches authentication):
//! - click a sidebar block: flip it lit/dim with a new code
//! - click a bar segment or elbow: cycle its color
//! - click CONDITION: green -> yellow -> red
//! - click a tab: switch screen; click inside a screen: ping / add contact
//! - click a data row: pin its highlight
//! - long press anywhere: toggle red alert

use super::{Env, Opts, Spec, Theme, need, num};
use crate::render::{
    Canvas, Rect, dim, hash, hash2, mix, rgb, scale, sd_round_box, text_width, unit,
};
use crate::ui::{Phase, Ui};
use std::f32::consts::TAU;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Palette {
    Amber,
    Blue,
}

#[derive(Clone)]
pub struct ConsoleOpts {
    pub palette: Palette,
    pub cycle_ms: u64,
    pub fps: u32,
    pub title: Option<String>,
}

impl Default for ConsoleOpts {
    fn default() -> Self {
        ConsoleOpts {
            palette: Palette::Amber,
            cycle_ms: 20_000,
            fps: 30,
            title: None,
        }
    }
}

pub fn parse(opts: &Opts) -> Result<Box<dyn Spec>, String> {
    parse_opts(opts).map(|o| Box::new(o) as Box<dyn Spec>)
}

fn parse_opts(opts: &Opts) -> Result<ConsoleOpts, String> {
    let mut o = ConsoleOpts::default();
    for &(k, v) in opts {
        match k {
            "palette" => {
                o.palette = match need(k, v)? {
                    "amber" => Palette::Amber,
                    "blue" => Palette::Blue,
                    p => return Err(format!("unknown palette {p} (amber, blue)")),
                }
            }
            "cycle" => o.cycle_ms = num::<u64>(k, v)?.clamp(3, 3600) * 1000,
            "fps" => o.fps = num::<u32>(k, v)?.clamp(1, 60),
            "title" => o.title = Some(need(k, v)?.to_string()),
            _ => return Err(format!("-bg console: unknown option {k}")),
        }
    }
    Ok(o)
}

impl Spec for ConsoleOpts {
    fn build(&self, env: &Env) -> Result<Box<dyn Theme>, String> {
        Ok(Box::new(Console::new(self.clone(), env.monitors, env.seed)))
    }
}

const BLACK: u32 = 0xff00_0000;
const WHITE: u32 = 0xffff_ffff;
const AMBER: [u32; 6] = [0xff9966, 0xffcc99, 0xcc99cc, 0x9999ff, 0xffaa33, 0xcc6666];
const BLUE: [u32; 6] = [0x5b8def, 0x9db8ff, 0x8a7fe0, 0xb7d0ff, 0x4f74c8, 0x88aadd];
const YELLOW: [u32; 6] = [0xffcc33, 0xffaa00, 0xffdd88, 0xcc9933, 0xffe0a0, 0xddaa44];
const RED: [u32; 6] = [0xff3b30, 0xcc2222, 0xff6f61, 0xaa1f1f, 0xff9a8f, 0xe04848];
const LONG_PRESS_MS: u64 = 700;
const PAGES: [&str; 4] = [
    "SENSOR SWEEP",
    "HARMONIC ANALYSIS",
    "POWER DISTRIBUTION",
    "STELLAR GRID",
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Condition {
    Green,
    Yellow,
    Red,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Hit {
    Cond,
    Elbow(usize),
    Block(usize),
    Seg(usize),
    Tab(usize),
    Page,
    Grid(usize),
    Nothing,
}

struct Elbow {
    r: Rect,
    arm: i32,
    bar: i32,
    outer: f32,
    inner: f32,
    top: bool,
    color: usize,
    code: u32,
    shown: u64,
}

struct Block {
    r: Rect,
    color: usize,
    code: u32,
    lit: bool,
    blink: Option<u64>,
    flash_until: u64,
    shown: u64,
}

struct Seg {
    r: Rect,
    color: usize,
    round_right: bool,
    bar: usize,
    shown: u64,
}

struct Panel {
    u: f32,
    seed: u64,
    sm: (i32, i32),
    md: (i32, i32),
    lg: (i32, i32),
    cond_r: Rect,
    cond_shown: u64,
    elbows: Vec<Elbow>,
    blocks: Vec<Block>,
    segs: Vec<Seg>,
    header_r: Rect,
    header_shown: u64,
    hgrid_r: Rect,
    grid_r: Rect,
    grid_hi: Option<usize>,
    grids_shown: u64,
    ptitle_r: Rect,
    tabs: Vec<Rect>,
    ptitle_shown: u64,
    page_r: Rect,
    auth_r: Rect,
    contacts: Vec<(f32, f32, u32)>,
    targets: Vec<(f32, f32, u32, u64)>,
    pings: Vec<(i32, i32, u64)>,
    boosts: Vec<(usize, u64)>,
    kick: Option<u64>,
}

struct Press {
    panel: usize,
    hit: Hit,
    t0: u64,
    fired: bool,
}

/// Values that are the same for every panel during one tick.
#[derive(Clone, Copy)]
struct Ctx<'a> {
    t: u64,
    pal: [u32; 6],
    blink_off: bool,
    red: bool,
    cond: Condition,
    page: usize,
    press: Option<(usize, Hit)>,
    title: &'a str,
}

pub struct Console {
    opts: ConsoleOpts,
    title: String,
    panels: Vec<Panel>,
    cond: Condition,
    page: usize,
    next_page: u64,
    press: Option<Press>,
    last_keys: u64,
    last_frame: u64,
    auth_shown: u64,
}

impl Console {
    pub fn new(opts: ConsoleOpts, monitors: &[Rect], seed: u64) -> Self {
        let title = opts.title.clone().unwrap_or_else(hostname).to_uppercase();
        let panels = monitors
            .iter()
            .enumerate()
            .map(|(i, m)| Panel::new(*m, hash2(seed, i as u64)))
            .collect();
        Console {
            next_page: opts.cycle_ms,
            opts,
            title,
            panels,
            cond: Condition::Green,
            page: 0,
            press: None,
            last_keys: 0,
            last_frame: 0,
            auth_shown: u64::MAX,
        }
    }

    pub fn frame_ms(&self) -> u64 {
        1000 / self.opts.fps.max(1) as u64
    }

    fn red(&self, ui: &Ui, t: u64) -> bool {
        self.cond == Condition::Red || ui.denied(t)
    }

    fn ctx(&self, ui: &Ui, t: u64) -> Ctx<'static> {
        let red = self.red(ui, t);
        let pal = if red {
            RED
        } else if self.cond == Condition::Yellow {
            YELLOW
        } else {
            match self.opts.palette {
                Palette::Amber => AMBER,
                Palette::Blue => BLUE,
            }
        };
        Ctx {
            t,
            pal,
            blink_off: red && (t / 450) % 2 == 1,
            red,
            cond: self.cond,
            page: self.page,
            press: self
                .press
                .as_ref()
                .filter(|p| !p.fired)
                .map(|p| (p.panel, p.hit)),
            title: "",
        }
    }

    fn hit(&self, x: i32, y: i32) -> Option<(usize, Hit)> {
        self.panels.iter().enumerate().find_map(|(i, p)| {
            let h = p.hit(x, y);
            (h != Hit::Nothing).then_some((i, h))
        })
    }
}

impl Theme for Console {
    /// Draw everything (first frame).
    fn draw_all(&mut self, c: &mut Canvas, t: u64, ui: &Ui) {
        for p in &mut self.panels {
            p.invalidate();
        }
        self.last_frame = 0;
        let mut d = Vec::new();
        self.tick(c, t, ui, &mut d);
    }

    /// Advance animations and redraw whatever changed into `c`.
    fn tick(&mut self, c: &mut Canvas, t: u64, ui: &Ui, dmg: &mut Vec<Rect>) -> Option<u64> {
        if let Some(p) = &mut self.press
            && !p.fired
            && t.saturating_sub(p.t0) >= LONG_PRESS_MS
        {
            p.fired = true;
            self.cond = if self.cond == Condition::Red {
                Condition::Green
            } else {
                Condition::Red
            };
        }
        if ui.keypresses != self.last_keys {
            self.last_keys = ui.keypresses;
            for (i, p) in self.panels.iter_mut().enumerate() {
                if !p.blocks.is_empty() {
                    let n = hash2(ui.keypresses, i as u64) as usize % p.blocks.len();
                    p.blocks[n].flash_until = t + 140;
                }
            }
        }
        if t >= self.next_page {
            self.page = (self.page + 1) % PAGES.len();
            self.next_page = t + self.opts.cycle_ms;
        }
        // frames on a fixed cadence; after a stall, restart it from now
        let fm = self.frame_ms();
        let frame = t + 1 >= self.last_frame + fm;
        if frame {
            self.last_frame = if t >= self.last_frame + 2 * fm {
                t
            } else {
                self.last_frame + fm
            };
        }
        let ctx = Ctx {
            title: &self.title,
            ..self.ctx(ui, t)
        };
        for (pi, p) in self.panels.iter_mut().enumerate() {
            p.update(pi, c, &ctx, frame, dmg);
        }
        // the auth panel is an overlay; repaint it when its animation advances
        let key = match ui.phase {
            Phase::Idle => t / 530,
            Phase::Typing => 0,
            Phase::Checking => t / 80,
            Phase::Denied => t / 250,
        } ^ ((ctx.pal[0] as u64) << 32);
        if key != self.auth_shown {
            self.auth_shown = key;
            dmg.extend(self.overlay_rects());
        }
        Some(self.last_frame + fm)
    }

    fn overlay_rects(&self) -> Vec<Rect> {
        self.panels.iter().map(|p| p.auth_r).collect()
    }

    fn overlay(&self, c: &mut Canvas, t: u64, ui: &Ui) {
        let ctx = self.ctx(ui, t);
        for p in &self.panels {
            if p.auth_r.overlaps(&c.clip()) {
                p.draw_auth(c, &ctx, ui);
            }
        }
    }

    fn press(&mut self, x: i32, y: i32, t: u64) {
        let (panel, hit) = self.hit(x, y).unwrap_or((0, Hit::Nothing));
        self.press = Some(Press {
            panel,
            hit,
            t0: t,
            fired: false,
        });
    }

    fn release(&mut self, x: i32, y: i32, t: u64) {
        let Some(p) = self.press.take() else { return };
        if p.fired || p.hit == Hit::Nothing || self.hit(x, y) != Some((p.panel, p.hit)) {
            return;
        }
        let page = self.page;
        let panel = &mut self.panels[p.panel];
        match p.hit {
            Hit::Cond => {
                self.cond = match self.cond {
                    Condition::Green => Condition::Yellow,
                    Condition::Yellow => Condition::Red,
                    Condition::Red => Condition::Green,
                }
            }
            Hit::Elbow(i) => panel.elbows[i].color = (panel.elbows[i].color + 1) % 6,
            Hit::Seg(i) => panel.segs[i].color = (panel.segs[i].color + 1) % 6,
            Hit::Block(i) => {
                let b = &mut panel.blocks[i];
                b.lit = !b.lit;
                b.code = (hash2(b.code as u64, t) % 1_000_000) as u32;
            }
            Hit::Tab(i) => {
                self.page = i;
                self.next_page = t + 3 * self.opts.cycle_ms;
            }
            Hit::Grid(row) => {
                panel.grid_hi = if panel.grid_hi == Some(row) {
                    None
                } else {
                    Some(row)
                }
            }
            Hit::Page => panel.click_page(page, x, y, t),
            Hit::Nothing => {}
        }
    }
}

fn hostname() -> String {
    let mut buf = [0u8; 256];
    // SAFETY: buf is valid for its length; gethostname NUL-terminates on success.
    let ok =
        unsafe { libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len() - 1) } == 0;
    let n = buf.iter().position(|&b| b == 0).unwrap_or(0);
    if ok && n > 0 {
        String::from_utf8_lossy(&buf[..n]).into_owned()
    } else {
        "CONSOLE".into()
    }
}

fn clock() -> (u64, String) {
    // SAFETY: plain libc time calls with valid out-pointers.
    unsafe {
        let now = libc::time(std::ptr::null_mut());
        let mut tm: libc::tm = std::mem::zeroed();
        libc::localtime_r(&now, &mut tm);
        (
            now as u64,
            format!(
                "{:04}.{:03}  {:02}:{:02}:{:02}",
                tm.tm_year + 1900,
                tm.tm_yday + 1,
                tm.tm_hour,
                tm.tm_min,
                tm.tm_sec
            ),
        )
    }
}

fn code_label(code: u32) -> String {
    format!("{:02}-{:04}", code / 10_000 % 100, code % 10_000)
}

impl Panel {
    fn new(mon: Rect, seed: u64) -> Panel {
        let u = (mon.h as f32).min(mon.w as f32 * 0.62) / 54.0;
        let u = u.max(6.0);
        let s = |k: f32| (k * u).round() as i32;
        let fs = |kx: f32, ky: f32| {
            (
                ((kx * u).round() as i32).max(1),
                ((ky * u).round() as i32).max(1),
            )
        };
        let (sm, md, lg) = (fs(0.10, 0.13), fs(0.16, 0.22), fs(0.30, 0.46));
        let pad = s(1.0);
        let (x0, x1, y0, y1) = (
            mon.x + pad,
            mon.right() - pad,
            mon.y + pad,
            mon.bottom() - pad,
        );
        let arm = s(8.0);
        let bar = s(1.4).max(4);
        let g = s(0.35).max(2);
        let ext = s(4.0);
        let (outer, inner) = (3.0 * u, 1.2 * u);
        let mut rnd = seed;
        let mut next = move || {
            rnd = hash(rnd);
            rnd
        };

        let mut elbows = Vec::new();
        let mut segs = Vec::new();
        let mut blocks = Vec::new();
        let mk_elbow = |r: Rect, top: bool, n: u64| Elbow {
            r,
            arm,
            bar,
            outer,
            inner,
            top,
            color: (n % 6) as usize,
            code: (hash(n) % 1_000_000) as u32,
            shown: u64::MAX,
        };
        let add_bar = |segs: &mut Vec<Seg>, y: i32, id: usize, n: &mut dyn FnMut() -> u64| {
            let start = x0 + arm + ext + g;
            let span = x1 - start;
            let mut x = start;
            while x < x1 {
                let mut w = ((0.05 + 0.28 * unit(n())) * span as f32) as i32;
                if x1 - (x + w) < s(3.0) {
                    w = x1 - x;
                }
                let last = x + w >= x1;
                segs.push(Seg {
                    r: Rect::new(x, y, w, bar),
                    color: (n() % 6) as usize,
                    round_right: last,
                    bar: id,
                    shown: u64::MAX,
                });
                x += w + g;
            }
        };

        // upper frame: condition block above an elbow bending right at the bottom
        let ytop1 = y0 + ((y1 - y0) as f32 * 0.24) as i32;
        let split = y0 + ((ytop1 - y0) as f32 * 0.42) as i32;
        let cond_r = Rect::new(x0, y0, arm, split - g - y0);
        elbows.push(mk_elbow(
            Rect::new(x0, split, arm + ext, ytop1 - split),
            false,
            next(),
        ));
        add_bar(&mut segs, ytop1 - bar, 0, &mut next);
        let hx = x0 + arm + s(2.0);
        let header_h = ytop1 - bar - g - y0;
        let header_r = Rect::new(hx + (x1 - hx) / 3, y0, x1 - hx - (x1 - hx) / 3, header_h);
        let hgrid_r = Rect::new(hx, y0 + s(0.4), (x1 - hx) / 3 - s(1.5), header_h - s(0.8));

        // lower frame: elbow at top and bottom, blocks between
        let yb0 = ytop1 + g * 3;
        let eh = bar + s(3.0);
        elbows.push(mk_elbow(Rect::new(x0, yb0, arm + ext, eh), true, next()));
        add_bar(&mut segs, yb0, 1, &mut next);
        elbows.push(mk_elbow(
            Rect::new(x0, y1 - eh, arm + ext, eh),
            false,
            next(),
        ));
        add_bar(&mut segs, y1 - bar, 2, &mut next);
        let (by0, by1) = (yb0 + eh + g, y1 - eh - g);
        let avail = by1 - by0;
        let n = ((avail as f32 / (4.0 * u)) as usize).clamp(2, 8);
        let weights: Vec<f32> = (0..n).map(|_| 1.0 + 1.5 * unit(next())).collect();
        let total: f32 = weights.iter().sum();
        let free = (avail - g * (n as i32 - 1)).max(0) as f32;
        let mut y = by0;
        for (i, wgt) in weights.iter().enumerate() {
            let h = if i + 1 == n {
                by1 - y
            } else {
                (free * wgt / total) as i32
            };
            let r = next();
            blocks.push(Block {
                r: Rect::new(x0, y, arm, h),
                color: (r % 6) as usize,
                code: (hash(r) % 1_000_000) as u32,
                lit: r % 7 != 0,
                blink: (r % 4 == 0).then_some(500 + r % 900),
                flash_until: 0,
                shown: u64::MAX,
            });
            y += h + g;
        }

        // content
        let cx0 = x0 + arm + s(2.0);
        let cy0 = yb0 + bar + s(1.2);
        let content = Rect::new(cx0, cy0, x1 - cx0, (y1 - bar - s(1.2)) - cy0);
        let left_w = (content.w as f32 * 0.58) as i32;
        let th = md.1 * 7 + s(0.6);
        let ptitle_r = Rect::new(content.x, content.y, left_w, th);
        let tab_w = text_width("00", sm.0) + s(1.6);
        let tabs = (0..PAGES.len())
            .map(|i| {
                let x = ptitle_r.right() - (PAGES.len() - i) as i32 * (tab_w + g);
                Rect::new(x, ptitle_r.y, tab_w, th)
            })
            .collect();
        let page_r = Rect::new(
            content.x,
            ptitle_r.bottom() + g * 2,
            left_w,
            content.bottom() - ptitle_r.bottom() - g * 2,
        );
        let rx = content.x + left_w + s(1.5);
        let rw = content.right() - rx;
        let grid_r = Rect::new(rx, content.y, rw, content.h * 45 / 100);
        let auth_r = Rect::new(
            rx,
            grid_r.bottom() + s(1.5),
            rw,
            content.bottom() - grid_r.bottom() - s(1.5),
        );

        let contacts = (0..6)
            .map(|_| {
                (
                    unit(next()) * TAU,
                    0.25 + 0.7 * unit(next()),
                    (next() % 900) as u32 + 100,
                )
            })
            .collect();

        Panel {
            u,
            seed,
            sm,
            md,
            lg,
            cond_r,
            cond_shown: u64::MAX,
            elbows,
            blocks,
            segs,
            header_r,
            header_shown: u64::MAX,
            hgrid_r,
            grid_r,
            grid_hi: None,
            grids_shown: u64::MAX,
            ptitle_r,
            tabs,
            ptitle_shown: u64::MAX,
            page_r,
            auth_r,
            contacts,
            targets: Vec::new(),
            pings: Vec::new(),
            boosts: Vec::new(),
            kick: None,
        }
    }

    fn invalidate(&mut self) {
        self.cond_shown = u64::MAX;
        self.header_shown = u64::MAX;
        self.grids_shown = u64::MAX;
        self.ptitle_shown = u64::MAX;
        self.elbows.iter_mut().for_each(|e| e.shown = u64::MAX);
        self.blocks.iter_mut().for_each(|b| b.shown = u64::MAX);
        self.segs.iter_mut().for_each(|s| s.shown = u64::MAX);
    }

    fn hit(&self, x: i32, y: i32) -> Hit {
        if self.cond_r.contains(x, y) {
            return Hit::Cond;
        }
        if let Some(i) = self.tabs.iter().position(|r| r.contains(x, y)) {
            return Hit::Tab(i);
        }
        if let Some(i) = self.elbows.iter().position(|e| e.r.contains(x, y)) {
            return Hit::Elbow(i);
        }
        if let Some(i) = self.blocks.iter().position(|b| b.r.contains(x, y)) {
            return Hit::Block(i);
        }
        if let Some(i) = self.segs.iter().position(|s| s.r.contains(x, y)) {
            return Hit::Seg(i);
        }
        if self.page_r.contains(x, y) {
            return Hit::Page;
        }
        if self.grid_r.contains(x, y) {
            return Hit::Grid(((y - self.grid_r.y) / self.line_h()) as usize);
        }
        Hit::Nothing
    }

    fn line_h(&self) -> i32 {
        self.sm.1 * 10
    }

    fn chrome(&self, ctx: &Ctx, base: u32, pressed: bool) -> u32 {
        if pressed {
            WHITE
        } else if ctx.blink_off {
            dim(rgb(base), 0.3)
        } else {
            rgb(base)
        }
    }

    fn update(&mut self, pi: usize, c: &mut Canvas, ctx: &Ctx, frame: bool, dmg: &mut Vec<Rect>) {
        let t = ctx.t;
        let pressed = |h: Hit| ctx.press == Some((pi, h));

        // condition block
        let cc = match ctx.cond {
            Condition::Green => 0x55cc77,
            Condition::Yellow => 0xffcc33,
            Condition::Red => 0xff3b30,
        };
        let col = self.chrome(ctx, cc, pressed(Hit::Cond));
        if col as u64 != self.cond_shown {
            self.cond_shown = col as u64;
            let r = self.cond_r;
            c.fill_rect(r, BLACK);
            c.round_rect(r, [self.u * 3.0, 0.0, 0.0, 0.0], col);
            let p = (self.u * 0.5) as i32;
            let w = text_width("CONDITION", self.sm.0);
            c.text(
                r.right() - p - w,
                r.y + p,
                "CONDITION",
                self.sm.0,
                self.sm.1,
                BLACK,
            );
            let word = match ctx.cond {
                Condition::Green => "GREEN",
                Condition::Yellow => "YELLOW",
                Condition::Red => "RED",
            };
            let w = text_width(word, self.md.0);
            c.text(
                r.right() - p - w,
                r.bottom() - p - 7 * self.md.1,
                word,
                self.md.0,
                self.md.1,
                BLACK,
            );
            dmg.push(r);
        }

        for i in 0..self.elbows.len() {
            let e = &self.elbows[i];
            let col = self.chrome(ctx, ctx.pal[e.color], pressed(Hit::Elbow(i)));
            let key = (col as u64) << 32 | e.code as u64;
            if key != e.shown {
                draw_elbow(c, e, col, self.sm, self.u);
                dmg.push(e.r);
                self.elbows[i].shown = key;
            }
        }

        // the moving highlight that scans along each bar
        let scan = (t / 350) as usize;
        for i in 0..self.segs.len() {
            let s = &self.segs[i];
            let in_bar: Vec<usize> = (0..self.segs.len())
                .filter(|&j| self.segs[j].bar == s.bar)
                .collect();
            let lit = in_bar[(scan + s.bar * 3) % in_bar.len()] == i && !ctx.red;
            let mut col = self.chrome(ctx, ctx.pal[s.color], pressed(Hit::Seg(i)));
            if lit && col != WHITE {
                col = mix(col, WHITE, 0.45);
            }
            if col as u64 != s.shown {
                c.fill_rect(s.r, BLACK);
                let rad = if s.round_right {
                    s.r.h as f32 / 2.0
                } else {
                    0.0
                };
                c.round_rect(s.r, [0.0, rad, rad, 0.0], col);
                dmg.push(s.r);
                self.segs[i].shown = col as u64;
            }
        }

        for i in 0..self.blocks.len() {
            let b = &self.blocks[i];
            let mut col = self.chrome(ctx, ctx.pal[b.color], pressed(Hit::Block(i)));
            let blink_dim = b.blink.is_some_and(|p| (t / p) % 2 == 1);
            if col != WHITE {
                if !b.lit || blink_dim {
                    col = dim(col, 0.38);
                }
                if t < b.flash_until {
                    col = mix(col, WHITE, 0.75);
                }
            }
            let key = (col as u64) << 32 | b.code as u64;
            if key != b.shown {
                c.fill_rect(b.r, BLACK);
                c.fill_rect(b.r, col);
                let label = code_label(b.code);
                let p = (self.u * 0.4) as i32;
                let w = text_width(&label, self.sm.0);
                c.text(
                    b.r.right() - p - w,
                    b.r.bottom() - p - 7 * self.sm.1,
                    &label,
                    self.sm.0,
                    self.sm.1,
                    BLACK,
                );
                dmg.push(b.r);
                self.blocks[i].shown = key;
            }
        }

        // title and clock
        let (secs, clock) = clock();
        let key = secs ^ (ctx.pal[0] as u64) << 32 ^ (ctx.red as u64) << 63;
        if key != self.header_shown {
            self.header_shown = key;
            let r = self.header_r;
            c.fill_rect(r, BLACK);
            let title = if ctx.red {
                "ALERT CONDITION"
            } else {
                ctx.title
            };
            let tw = text_width(title, self.lg.0);
            let tcol = if ctx.blink_off {
                dim(rgb(ctx.pal[0]), 0.3)
            } else {
                rgb(ctx.pal[0])
            };
            c.text(r.right() - tw, r.y, title, self.lg.0, self.lg.1, tcol);
            let y = r.y + 7 * self.lg.1 + (self.u * 0.6) as i32;
            let sub = "CONSOLE SECURED";
            let sw = text_width(sub, self.md.0);
            c.text(
                r.right() - sw,
                y,
                sub,
                self.md.0,
                self.md.1,
                rgb(ctx.pal[2]),
            );
            let y = y + 7 * self.md.1 + (self.u * 0.5) as i32;
            let cw = text_width(&clock, self.md.0);
            c.text(
                r.right() - cw,
                y,
                &clock,
                self.md.0,
                self.md.1,
                rgb(ctx.pal[1]),
            );
            dmg.push(r);
        }

        let key = (t / 250)
            ^ ((ctx.pal[0] as u64) << 40)
            ^ self.grid_hi.map_or(0, |r| r as u64 + 1) << 56;
        if key != self.grids_shown {
            self.grids_shown = key;
            let auto_hi = (t / 900) as usize;
            self.draw_grid(c, self.hgrid_r, self.seed, ctx, Some(auto_hi), true);
            self.draw_grid(c, self.grid_r, self.seed ^ 0x55, ctx, self.grid_hi, false);
            dmg.push(self.hgrid_r);
            dmg.push(self.grid_r);
        }

        let tab_pressed = (0..self.tabs.len())
            .find(|&i| pressed(Hit::Tab(i)))
            .map_or(0, |i| i as u64 + 1);
        let key = ctx.page as u64 | tab_pressed << 8 | (ctx.pal[0] as u64) << 16;
        if key != self.ptitle_shown {
            self.ptitle_shown = key;
            self.draw_page_title(c, ctx, tab_pressed);
            dmg.push(self.ptitle_r);
        }

        if frame {
            self.pings.retain(|p| t.saturating_sub(p.2) < 900);
            self.targets.retain(|p| t.saturating_sub(p.3) < 30_000);
            self.boosts.retain(|b| t.saturating_sub(b.1) < 3_000);
            self.draw_page(c, ctx);
            dmg.push(self.page_r);
        }
    }

    fn draw_grid(
        &self,
        c: &mut Canvas,
        r: Rect,
        seed: u64,
        ctx: &Ctx,
        hi: Option<usize>,
        compact: bool,
    ) {
        c.fill_rect(r, BLACK);
        let (sx, sy) = self.sm;
        let lh = self.line_h();
        let rows = (r.h / lh).max(0) as usize;
        if rows == 0 {
            return;
        }
        let hi = hi.map(|h| h % rows);
        let cw = 6 * sx;
        for row in 0..rows {
            let y = r.y + row as i32 * lh;
            let is_hi = hi == Some(row);
            if is_hi {
                c.pill(
                    Rect::new(r.x, y, r.w, 7 * sy + 2 * sy),
                    rgb(ctx.pal[if compact { 3 } else { 0 }]),
                );
            }
            let mut x = r.x + cw;
            let mut col = 0u64;
            loop {
                let digits = 2 + (hash2(seed, col) % 5) as usize;
                let w = (digits as i32 + 2) * cw;
                if x + w > r.right() - cw {
                    break;
                }
                let cell = hash2(seed ^ (row as u64) << 20, col);
                if !cell.is_multiple_of(9) {
                    let period = 250 * (1 + cell % 12);
                    let v = hash2(cell, ctx.t / period) % 10u64.pow(digits as u32);
                    let s = format!("{v:0digits$}");
                    let color = if is_hi {
                        BLACK
                    } else {
                        let base = rgb(ctx.pal[((seed + col) % 6) as usize]);
                        if cell.is_multiple_of(5) {
                            dim(base, 0.55)
                        } else {
                            base
                        }
                    };
                    c.text(x, y + sy, &s, sx, sy, color);
                }
                x += w;
                col += 1;
            }
        }
    }

    fn draw_page_title(&self, c: &mut Canvas, ctx: &Ctx, tab_pressed: u64) {
        let r = self.ptitle_r;
        c.fill_rect(r, BLACK);
        let first_tab = self.tabs.first().map_or(r.right(), |t| t.x);
        let pill = Rect::new(r.x, r.y, first_tab - r.x - (self.u * 0.8) as i32, r.h);
        let col = rgb(ctx.pal[if ctx.red { 0 } else { 4 }]);
        c.round_rect(pill, [r.h as f32 / 2.0, 0.0, 0.0, r.h as f32 / 2.0], col);
        let label = format!(
            "{}  {:02}-{}",
            PAGES[ctx.page],
            ctx.page + 1,
            400 + self.seed % 600
        );
        let p = (self.u * 0.3) as i32;
        let w = text_width(&label, self.md.0);
        c.text(
            pill.right() - p - w,
            r.y + (r.h - 7 * self.md.1) / 2,
            &label,
            self.md.0,
            self.md.1,
            BLACK,
        );
        for (i, tr) in self.tabs.iter().enumerate() {
            let col = if tab_pressed == i as u64 + 1 {
                WHITE
            } else if i == ctx.page {
                rgb(ctx.pal[0])
            } else {
                dim(rgb(ctx.pal[3]), 0.55)
            };
            c.fill_rect(*tr, col);
            let s = format!("{:02}", i + 1);
            let w = text_width(&s, self.sm.0);
            c.text(
                tr.x + (tr.w - w) / 2,
                tr.y + (tr.h - 7 * self.sm.1) / 2,
                &s,
                self.sm.0,
                self.sm.1,
                BLACK,
            );
        }
    }

    fn radar_geom(&self) -> (f32, f32, f32) {
        let r = self.page_r;
        let rad = (r.w.min(r.h) as f32 / 2.0 - 2.5 * self.u).max(8.0);
        (
            r.x as f32 + r.w as f32 / 2.0,
            r.y as f32 + r.h as f32 / 2.0,
            rad,
        )
    }

    fn click_page(&mut self, page: usize, x: i32, y: i32, t: u64) {
        self.pings.push((x, y, t));
        let r = self.page_r;
        match page {
            0 => {
                let (cx, cy, rad) = self.radar_geom();
                let (dx, dy) = (x as f32 - cx, y as f32 - cy);
                let d = (dx * dx + dy * dy).sqrt() / rad;
                if d <= 1.0 {
                    let id = (hash2(t, self.seed) % 900) as u32 + 100;
                    self.contacts.push((dx.atan2(-dy).rem_euclid(TAU), d, id));
                    if self.contacts.len() > 24 {
                        self.contacts.remove(6);
                    }
                }
            }
            1 => self.kick = Some(t),
            2 => {
                let i = ((x - r.x) * 12 / r.w.max(1)).clamp(0, 11) as usize;
                self.boosts.push((i, t));
            }
            _ => {
                let nx = (x - r.x) as f32 / r.w.max(1) as f32;
                let ny = (y - r.y) as f32 / r.h.max(1) as f32;
                self.targets
                    .push((nx, ny, (hash2(t, 7) % 9000) as u32 + 1000, t));
            }
        }
    }

    fn draw_page(&self, out: &mut Canvas, ctx: &Ctx) {
        // draw into a page-sized canvas so nothing leaks outside the page
        let r = self.page_r;
        let c = &mut Canvas::new(r, BLACK);
        match ctx.page {
            0 => self.page_radar(c, ctx),
            1 => self.page_harmonic(c, ctx),
            2 => self.page_power(c, ctx),
            _ => self.page_stellar(c, ctx),
        }
        for &(x, y, t0) in &self.pings {
            let k = (ctx.t.saturating_sub(t0)) as f32 / 900.0;
            let rad = 6.0 * self.u * k;
            c.ring(
                x as f32,
                y as f32,
                rad + 1.5,
                (rad - 1.5).max(0.0),
                scale(WHITE, 1.0 - k),
            );
        }
        out.copy_from(c);
    }

    fn page_radar(&self, c: &mut Canvas, ctx: &Ctx) {
        let (cx, cy, rad) = self.radar_geom();
        let faint = dim(rgb(ctx.pal[3]), 0.55);
        for k in 1..=4 {
            let rr = rad * k as f32 / 4.0;
            c.ring(cx, cy, rr + 0.8, rr - 0.8, faint);
        }
        c.fill_rect(
            Rect::new((cx - rad) as i32, cy as i32, (2.0 * rad) as i32, 1),
            faint,
        );
        c.fill_rect(
            Rect::new(cx as i32, (cy - rad) as i32, 1, (2.0 * rad) as i32),
            faint,
        );
        for d in 0..36 {
            let a = d as f32 * TAU / 36.0;
            let len = if d % 3 == 0 { 0.06 } else { 0.03 };
            let (s, co) = a.sin_cos();
            c.line(
                cx + s * rad,
                cy - co * rad,
                cx + s * rad * (1.0 + len),
                cy - co * rad * (1.0 + len),
                1.2,
                faint,
            );
        }
        let (sx, sy) = self.sm;
        for (i, lbl) in ["000", "090", "180", "270"].iter().enumerate() {
            let a = i as f32 * TAU / 4.0;
            let (s, co) = a.sin_cos();
            let w = text_width(lbl, sx);
            let (lx, ly) = (
                cx + s * (rad + 1.3 * self.u),
                cy - co * (rad + 1.3 * self.u),
            );
            c.text(
                lx as i32 - w / 2,
                ly as i32 - 7 * sy / 2,
                lbl,
                sx,
                sy,
                rgb(ctx.pal[1]),
            );
        }

        // sweep with a fading trail, only evaluated inside the trail's bounding box
        let ang = (ctx.t % 4000) as f32 / 4000.0 * TAU;
        let trail = 1.0f32;
        let mut pts = vec![(cx, cy)];
        for k in 0..=8 {
            let a = ang - trail * k as f32 / 8.0;
            pts.push((cx + a.sin() * rad, cy - a.cos() * rad));
        }
        let (mut bx0, mut by0, mut bx1, mut by1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
        for (x, y) in pts {
            bx0 = bx0.min(x);
            by0 = by0.min(y);
            bx1 = bx1.max(x);
            by1 = by1.max(y);
        }
        let bb = Rect::new(
            bx0 as i32 - 2,
            by0 as i32 - 2,
            (bx1 - bx0) as i32 + 4,
            (by1 - by0) as i32 + 4,
        )
        .intersect(&c.clip());
        let sweep = rgb(ctx.pal[1]);
        for y in bb.y..bb.bottom() {
            for x in bb.x..bb.right() {
                let (dx, dy) = (x as f32 + 0.5 - cx, y as f32 + 0.5 - cy);
                if dx * dx + dy * dy > rad * rad {
                    continue;
                }
                let diff = (ang - dx.atan2(-dy)).rem_euclid(TAU);
                if diff < trail {
                    c.blend(x, y, scale(sweep, 0.42 * (1.0 - diff / trail).powi(2)));
                }
            }
        }
        c.line(
            cx,
            cy,
            cx + ang.sin() * rad,
            cy - ang.cos() * rad,
            2.0,
            sweep,
        );

        for &(a, d, id) in &self.contacts {
            let since = (ang - a).rem_euclid(TAU) / TAU;
            let bright = (1.0 - since).powi(3);
            let (px, py) = (cx + a.sin() * rad * d, cy - a.cos() * rad * d);
            c.ring(
                px,
                py,
                0.22 * self.u,
                0.0,
                scale(rgb(ctx.pal[0]), 0.2 + 0.8 * bright),
            );
            if bright > 0.35 {
                c.text(
                    px as i32 + (0.4 * self.u) as i32,
                    py as i32,
                    &format!("C-{id}"),
                    sx,
                    sy,
                    scale(rgb(ctx.pal[0]), bright),
                );
            }
        }
    }

    fn page_harmonic(&self, c: &mut Canvas, ctx: &Ctx) {
        let r = self.page_r;
        let faint = dim(rgb(ctx.pal[3]), 0.3);
        for i in 0..=12 {
            c.fill_rect(Rect::new(r.x + r.w * i / 12, r.y, 1, r.h), faint);
        }
        for i in 0..=8 {
            c.fill_rect(Rect::new(r.x, r.y + r.h * i / 8, r.w, 1), faint);
        }
        let t = ctx.t as f32 / 1000.0;
        let burst = self.kick.map_or(0.0, |k| {
            1.5 * (-((ctx.t.saturating_sub(k)) as f32) / 700.0).exp()
        });
        let th = (self.u * 0.15).max(2.0) as i32;
        for w in 0..3 {
            let cy = r.y as f32 + r.h as f32 * (w as f32 + 1.0) / 4.0;
            let amp = r.h as f32 / 11.0 * (1.0 + burst);
            let (f1, f2) = (0.018 + w as f32 * 0.009, 0.051 - w as f32 * 0.007);
            let col = rgb(ctx.pal[[0, 1, 3][w]]);
            let mut prev = None;
            for x in 0..r.w {
                let fx = x as f32;
                let y = cy
                    + amp
                        * (0.6 * (fx * f1 + t * (1.3 + w as f32)).sin()
                            + 0.4 * (fx * f2 - t * 2.1).sin());
                let y = y as i32;
                let (a, b) = match prev {
                    Some(p) => (y.min(p), y.max(p)),
                    None => (y, y),
                };
                c.fill_rect(Rect::new(r.x + x, a - th / 2, 1, b - a + th), col);
                prev = Some(y);
            }
            let lbl = format!(
                "H{} {:.4}",
                w + 1,
                0.3 + 0.2 * (t * (0.7 + w as f32)).sin().abs() + burst / 3.0
            );
            c.text(
                r.x + (self.u * 0.5) as i32,
                cy as i32 - (amp as i32) - 8 * self.sm.1,
                &lbl,
                self.sm.0,
                self.sm.1,
                col,
            );
        }
    }

    fn page_power(&self, c: &mut Canvas, ctx: &Ctx) {
        let r = self.page_r;
        let n = 12;
        let label_h = 7 * self.sm.1 + (self.u * 0.6) as i32;
        let h = r.h - label_h - (self.u * 0.5) as i32;
        let slot = r.w / n;
        let bw = (slot as f32 * 0.68) as i32;
        let segs = 20;
        let sh = (h / segs).max(2);
        let t = ctx.t as f32;
        for i in 0..n as usize {
            let fi = i as f32;
            let mut lvl = 0.45
                + 0.25 * (t * 0.0011 * (1.0 + fi * 0.13) + fi).sin()
                + 0.15 * (t * 0.0037 + fi * 2.1).sin();
            for &(b, t0) in &self.boosts {
                if b == i {
                    lvl += 0.6 * (-((ctx.t.saturating_sub(t0)) as f32) / 900.0).exp();
                }
            }
            let lit = (lvl.clamp(0.04, 1.0) * segs as f32) as i32;
            let x = r.x + i as i32 * slot + (slot - bw) / 2;
            for s in 0..segs {
                let y = r.y + h - (s + 1) * sh;
                let col = if s >= lit {
                    dim(rgb(ctx.pal[3]), 0.15)
                } else if s >= 17 {
                    rgb(ctx.pal[5])
                } else if s >= 11 {
                    rgb(ctx.pal[0])
                } else {
                    rgb(ctx.pal[3])
                };
                c.fill_rect(Rect::new(x, y + 1, bw, sh - 2), col);
            }
            let lbl = format!("{}{}", ['A', 'B', 'C'][i / 4], i % 4 + 1);
            let w = text_width(&lbl, self.sm.0);
            c.text(
                x + (bw - w) / 2,
                r.y + h + (self.u * 0.4) as i32,
                &lbl,
                self.sm.0,
                self.sm.1,
                rgb(ctx.pal[1]),
            );
        }
        let ty = r.y + h - 17 * sh;
        let mut x = r.x;
        while x < r.right() {
            c.fill_rect(Rect::new(x, ty, (self.u * 0.6) as i32, 1), rgb(ctx.pal[5]));
            x += (self.u * 1.0) as i32;
        }
    }

    fn page_stellar(&self, c: &mut Canvas, ctx: &Ctx) {
        let r = self.page_r;
        let faint = dim(rgb(ctx.pal[3]), 0.28);
        for i in 1..8 {
            c.fill_rect(Rect::new(r.x + r.w * i / 8, r.y, 1, r.h), faint);
            c.fill_rect(Rect::new(r.x, r.y + r.h * i / 8, r.w, 1), faint);
        }
        let t = ctx.t as f32;
        for i in 0..160u64 {
            let h = hash2(self.seed, i);
            let speed = 0.002 + 0.01 * unit(hash(h));
            let x = (unit(h) * r.w as f32 + t * speed).rem_euclid(r.w as f32);
            let y = unit(hash(h ^ 0x5bd1)) * r.h as f32;
            let tw = 0.55 + 0.45 * (t * 0.002 + i as f32).sin();
            let sz = if h.is_multiple_of(11) { 2 } else { 1 };
            c.fill_rect(
                Rect::new(r.x + x as i32, r.y + y as i32, sz, sz),
                scale(WHITE, tw),
            );
        }
        let bracket = |c: &mut Canvas, x: i32, y: i32, s: i32, col: u32| {
            let l = s / 3;
            for (dx, dy) in [(-1, -1), (1, -1), (1, 1), (-1, 1)] {
                let (cx, cy) = (x + dx * s, y + dy * s);
                c.fill_rect(Rect::new(cx.min(cx - dx * l), cy, l, 2), col);
                c.fill_rect(Rect::new(cx, cy.min(cy - dy * l), 2, l), col);
            }
        };
        let (nx, ny) = (
            0.5 + 0.35 * (t * 0.00021).sin(),
            0.5 + 0.3 * (t * 0.00033 + 1.0).sin(),
        );
        let (tx, ty) = (
            r.x + (nx * r.w as f32) as i32,
            r.y + (ny * r.h as f32) as i32,
        );
        let s = (self.u * 1.2) as i32;
        bracket(c, tx, ty, s, rgb(ctx.pal[0]));
        c.ring(tx as f32, ty as f32, 3.0, 0.0, rgb(ctx.pal[0]));
        let info = format!("TRK 0042  X {:.3} Y {:.3}", nx, ny);
        c.text(
            tx + s + 4,
            ty - s,
            &info,
            self.sm.0,
            self.sm.1,
            rgb(ctx.pal[0]),
        );
        for &(nx, ny, id, t0) in &self.targets {
            let (x, y) = (
                r.x + (nx * r.w as f32) as i32,
                r.y + (ny * r.h as f32) as i32,
            );
            let pulse = 0.6 + 0.4 * ((ctx.t - t0) as f32 * 0.008).sin();
            bracket(
                c,
                x,
                y,
                (s as f32 * 0.8) as i32,
                scale(rgb(ctx.pal[4]), pulse),
            );
            c.text(
                x + s,
                y - s,
                &format!("TRK {id}"),
                self.sm.0,
                self.sm.1,
                rgb(ctx.pal[4]),
            );
        }
    }

    fn draw_auth(&self, c: &mut Canvas, ctx: &Ctx, ui: &Ui) {
        let r = self.auth_r;
        if r.h < 7 * self.md.1 * 3 {
            return;
        }
        c.fill_rect(r, BLACK);
        let denied = ui.denied(ctx.t);
        let hh = 7 * self.md.1 + (self.u * 0.8) as i32;
        let head = Rect::new(r.x, r.y, r.w, hh);
        c.round_rect(
            head,
            [hh as f32 / 2.0, 0.0, 0.0, 0.0],
            rgb(ctx.pal[if denied { 0 } else { 2 }]),
        );
        let p = (self.u * 0.5) as i32;
        let label = "AUTHORIZATION";
        let w = text_width(label, self.md.0);
        c.text(
            head.right() - p - w,
            head.y + (hh - 7 * self.md.1) / 2,
            label,
            self.md.0,
            self.md.1,
            BLACK,
        );
        // side rail
        let rail = (self.u * 0.6) as i32;
        c.fill_rect(
            Rect::new(
                r.x,
                head.bottom() + p / 2,
                rail,
                r.bottom() - head.bottom() - p / 2,
            ),
            rgb(ctx.pal[2]),
        );

        let x = r.x + rail + p * 2;
        let mut y = head.bottom() + p * 2;
        let (sx, sy) = self.md;
        let (status, col) = match ui.phase {
            _ if denied => (
                "ACCESS DENIED",
                if (ctx.t / 250).is_multiple_of(2) {
                    rgb(RED[0])
                } else {
                    rgb(RED[3])
                },
            ),
            Phase::Checking => ("VERIFYING", rgb(ctx.pal[4])),
            Phase::Typing => ("ACCESS CODE", rgb(ctx.pal[1])),
            _ => ("ENTER ACCESS CODE", rgb(ctx.pal[1])),
        };
        let w = c.text(x, y, status, sx, sy, col);
        if ui.phase == Phase::Idle && (ctx.t / 530).is_multiple_of(2) {
            c.fill_rect(Rect::new(x + w + sx * 2, y, sx * 4, 7 * sy), col);
        }
        y += 7 * sy + p * 2;
        if ui.phase == Phase::Typing {
            let d = 4 * sx;
            let max = ((r.right() - x) / (d + sx * 2)).max(1) as usize;
            for i in 0..ui.len.min(max) {
                c.pill(
                    Rect::new(x + i as i32 * (d + sx * 2), y, d, 4 * sy),
                    rgb(ctx.pal[0]),
                );
            }
        } else if ui.phase == Phase::Checking {
            let bw = r.right() - x - p;
            let seg = bw / 10;
            let k = (ctx.t / 80) as i32 % 10;
            for i in 0..10 {
                let col = if i == k {
                    WHITE
                } else {
                    rgb(ctx.pal[if i < k { 4 } else { 3 }])
                };
                c.fill_rect(Rect::new(x + i * seg, y, seg - sx, 4 * sy), col);
            }
        }
        y += 4 * sy + p * 2;
        if let Some(msg) = &ui.message {
            let (sx, sy) = self.sm;
            let per = ((r.right() - x) / (6 * sx)).max(4) as usize;
            let mut line = String::new();
            let mut lines = Vec::new();
            for word in msg.split_whitespace() {
                if !line.is_empty() && line.len() + 1 + word.len() > per {
                    lines.push(std::mem::take(&mut line));
                }
                if !line.is_empty() {
                    line.push(' ');
                }
                line.push_str(word);
            }
            lines.push(line);
            for l in lines.iter().take(3) {
                if y + 7 * sy > r.bottom() {
                    break;
                }
                c.text(x, y, l, sx, sy, rgb(ctx.pal[4]));
                y += 10 * sy;
            }
        }
    }
}

fn draw_elbow(c: &mut Canvas, e: &Elbow, col: u32, sm: (i32, i32), u: f32) {
    c.fill_rect(e.r, BLACK);
    let (x0, y0, x1, y1) = (
        e.r.x as f32,
        e.r.y as f32,
        e.r.right() as f32,
        e.r.bottom() as f32,
    );
    let (arm, bar, big) = (e.arm as f32, e.bar as f32, 1.0e5);
    let (outer, inner) = (e.outer, e.inner);
    let p = (u * 0.4) as i32;
    let label = code_label(e.code);
    let w = text_width(&label, sm.0);
    let lx = e.r.x + e.arm - p - w;
    if e.top {
        c.fill_sdf(e.r, col, |x, y| {
            let o = sd_round_box(x, y, x0, y0, x1, y1, [outer, 0.0, 0.0, 0.0]);
            let cut = sd_round_box(
                x,
                y,
                x0 + arm,
                y0 + bar,
                x1 + big,
                y1 + big,
                [inner, 0.0, 0.0, 0.0],
            );
            o.max(-cut)
        });
        c.text(lx, e.r.bottom() - p - 7 * sm.1, &label, sm.0, sm.1, BLACK);
    } else {
        c.fill_sdf(e.r, col, |x, y| {
            let o = sd_round_box(x, y, x0, y0, x1, y1, [0.0, 0.0, 0.0, outer]);
            let cut = sd_round_box(
                x,
                y,
                x0 + arm,
                y0 - big,
                x1 + big,
                y1 - bar,
                [0.0, 0.0, 0.0, inner],
            );
            o.max(-cut)
        });
        c.text(lx, e.r.y + p, &label, sm.0, sm.1, BLACK);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn options() {
        let o = parse_opts(&[("palette", Some("blue")), ("fps", Some("90"))]).unwrap();
        assert_eq!(o.palette, Palette::Blue);
        assert_eq!(o.fps, 60);
        assert!(parse_opts(&[("palette", Some("pink"))]).is_err());
        assert!(parse_opts(&[("bogus", None)]).is_err());
    }

    #[test]
    fn frames_keep_cadence() {
        let mon = Rect::new(0, 0, 640, 400);
        let mut con = Console::new(ConsoleOpts::default(), &[mon], 1);
        let mut c = Canvas::new(mon, BLACK);
        let ui = Ui::new();
        con.draw_all(&mut c, 1000, &ui);
        let mut d = Vec::new();
        // waking a few ms late must not push the whole cadence back
        let next = con.tick(&mut c, 1035, &ui, &mut d).unwrap();
        assert_eq!(next, 1000 + 2 * con.frame_ms());
        // a long stall restarts the cadence from now
        let next = con.tick(&mut c, 5000, &ui, &mut d).unwrap();
        assert_eq!(next, 5000 + con.frame_ms());
    }

    #[test]
    fn interaction_cycles() {
        let mon = Rect::new(0, 0, 1920, 1080);
        let mut con = Console::new(ConsoleOpts::default(), &[mon], 1);
        let mut c = Canvas::new(mon, BLACK);
        let ui = Ui::new();
        con.draw_all(&mut c, 1, &ui);

        // click CONDITION twice -> red
        let cr = con.panels[0].cond_r;
        for t in [10, 20] {
            con.press(cr.x + 5, cr.y + 5, t);
            con.release(cr.x + 5, cr.y + 5, t + 50);
        }
        assert_eq!(con.cond, Condition::Red);

        // long press anywhere toggles red alert back off
        con.press(5, 5, 1000);
        let mut d = Vec::new();
        con.tick(&mut c, 1000 + LONG_PRESS_MS, &ui, &mut d);
        con.release(5, 5, 1000 + LONG_PRESS_MS + 10);
        assert_eq!(con.cond, Condition::Green);

        // block flips
        let b = con.panels[0].blocks[0].r;
        let was = con.panels[0].blocks[0].lit;
        con.press(b.x + 2, b.y + 2, 5000);
        con.release(b.x + 2, b.y + 2, 5010);
        assert_ne!(con.panels[0].blocks[0].lit, was);

        // tab switches page
        let tab = con.panels[0].tabs[2];
        con.press(tab.x + 1, tab.y + 1, 6000);
        con.release(tab.x + 1, tab.y + 1, 6010);
        assert_eq!(con.page, 2);

        // every page renders without panicking, also on a tiny monitor
        for page in 0..4 {
            con.page = page;
            con.tick(&mut c, 7000 + page as u64 * 100, &ui, &mut d);
        }
        let tiny = Rect::new(0, 0, 160, 100);
        let mut con = Console::new(ConsoleOpts::default(), &[tiny], 2);
        let mut c = Canvas::new(tiny, BLACK);
        for page in 0..4 {
            con.page = page;
            con.draw_all(&mut c, 50 + page as u64 * 100, &ui);
            con.overlay(&mut c, 50, &ui);
        }
    }
}

#[cfg(test)]
mod fuzz {
    use super::*;

    /// Whoever stands in front of a locked screen can click and type at
    /// will. Throw random input at every layout, including absurd ones.
    #[test]
    fn random_input_never_panics() {
        let sizes = [
            (1, 1),
            (7, 300),
            (300, 7),
            (64, 48),
            (160, 100),
            (641, 479),
            (1280, 720),
            (2560, 360),
        ];
        for (n, (w, h)) in sizes.into_iter().enumerate() {
            let mons = [
                Rect::new(0, 0, w, h),
                Rect::new(w, 3, h.min(400), w.min(300)),
            ];
            let full = mons[0].union(&mons[1]);
            let mut con = Console::new(ConsoleOpts::default(), &mons, n as u64);
            let mut c = Canvas::new(full, BLACK);
            let mut ui = Ui::new();
            let mut d = Vec::new();
            let mut t = 0u64;
            con.draw_all(&mut c, t, &ui);
            for i in 0..500u64 {
                let r = hash2(n as u64, i);
                t += r % 900;
                let x = (r >> 8) as i32 % (full.w + 40) - 20;
                let y = (r >> 24) as i32 % (full.h + 40) - 20;
                match r >> 40 & 7 {
                    0 | 1 => con.press(x, y, t),
                    2 | 3 => con.release(x, y, t),
                    4 => {
                        ui.keypresses += 1;
                        ui.len = (r >> 44) as usize % 300;
                        ui.phase = [Phase::Idle, Phase::Typing, Phase::Checking, Phase::Denied]
                            [(r >> 52) as usize % 4];
                        ui.denied_until = t + 500;
                        ui.message = (r >> 56 & 1 == 1).then(|| "Place your finger ".repeat(40));
                    }
                    5 => con.page = (r >> 44) as usize % PAGES.len(),
                    _ => {}
                }
                con.tick(&mut c, t, &ui, &mut d);
                for r in con.overlay_rects() {
                    c.set_clip(Some(r));
                    con.overlay(&mut c, t, &ui);
                }
                c.set_clip(None);
                d.clear();
            }
        }
    }
}

#[cfg(test)]
mod bench {
    use super::*;
    use std::time::Instant;

    #[test]
    #[ignore]
    fn frame_cost() {
        for (w, h) in [(1920, 1080), (2560, 1440), (3840, 2160)] {
            let mon = Rect::new(0, 0, w, h);
            let mut con = Console::new(ConsoleOpts::default(), &[mon], 1);
            let mut c = Canvas::new(mon, BLACK);
            let ui = Ui::new();
            con.draw_all(&mut c, 1, &ui);
            let mut t = 10_000u64;
            for page in 0..4 {
                con.page = page;
                con.next_page = u64::MAX;
                let n = 60;
                let mut tick_ns = 0u128;
                let mut px = 0i64;
                let mut present_ns = 0u128;
                for _ in 0..n {
                    t += 67;
                    let mut d = Vec::new();
                    let a = Instant::now();
                    con.tick(&mut c, t, &ui, &mut d);
                    tick_ns += a.elapsed().as_nanos();
                    // mimic Locker::present: copy, overlay, byte-swap into a buffer
                    let a = Instant::now();
                    for r in &d {
                        let mut o = Canvas::new(*r, BLACK);
                        o.copy_from(&c);
                        con.overlay(&mut o, t, &ui);
                        let mut buf = Vec::with_capacity(o.px.len() * 4);
                        for p in &o.px {
                            buf.extend_from_slice(&p.to_le_bytes());
                        }
                        std::hint::black_box(&buf);
                        px += r.area();
                    }
                    present_ns += a.elapsed().as_nanos();
                }
                println!(
                    "{w}x{h} page {page}: tick {:.2} ms, present-prep {:.2} ms, {:.0} kpx/frame",
                    tick_ns as f64 / n as f64 / 1e6,
                    present_ns as f64 / n as f64 / 1e6,
                    px as f64 / n as f64 / 1e3
                );
            }
        }
    }
}
